describe('Lazy-Loaded Components - Smooth Appearance', () => {
  beforeEach(() => {
    cy.visit('/lazy-load-demo');
  });

  it('should load lazy components smoothly without layout shift', () => {
    // Verify initial page loads without lazy components
    cy.get('[data-testid="initial-content"]').should('be.visible');
    cy.get('[data-testid="lazy-component-placeholder"]').should('be.visible');
    cy.get('[data-testid="lazy-component-placeholder"]').should('contain', 'Loading...');

    // Scroll to trigger lazy loading
    cy.get('body').scrollTo('bottom');

    // Wait for lazy component to load
    cy.get('[data-testid="lazy-component"]').should('be.visible');
    cy.get('[data-testid="lazy-component"]').should('not.have.class', 'loading');
    cy.get('[data-testid="lazy-component"]').should('contain', 'Loaded Content');

    // Verify no layout shift occurred
    cy.get('[data-testid="initial-content"]').should('have.height', 100);
    cy.get('[data-testid="lazy-component"]').should('have.height', 200);
    cy.get('[data-testid="initial-content"]').should('have.width', 1000);
    cy.get('[data-testid="lazy-component"]').should('have.width', 1000);

    // Verify smooth transition animation
    cy.get('[data-testid="lazy-component"]').should('have.class', 'fade-in');
    cy.get('[data-testid="lazy-component"]').should('have.css', 'opacity', '1');
  });

  it('should handle failed lazy component loading gracefully', () => {
    // Intercept the API call for the lazy component and simulate failure
    cy.intercept('GET', '/api/lazy-component-data', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('lazyComponentLoad');

    // Scroll to trigger lazy loading
    cy.get('body').scrollTo('bottom');

    // Wait for the failed load attempt
    cy.wait('@lazyComponentLoad');

    // Verify error state is displayed instead of component
    cy.get('[data-testid="lazy-component-placeholder"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to load');

    // Verify fallback UI is shown
    cy.get('[data-testid="fallback-ui"]').should('be.visible');
    cy.get('[data-testid="fallback-ui"]').should('contain', 'Try refreshing');

    // Verify no layout shift occurred due to failed load
    cy.get('[data-testid="initial-content"]').should('have.height', 100);
    cy.get('[data-testid="error-message"]').should('have.height', 50);
  });
});
